import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun main() = runBlocking {
    try {
        flow { emit(1); emit(2) }
            .catch { println("upstream caught") }
            .collect {
                println("got $it")
                check(it != 1)
            }
    } catch (e: IllegalStateException) {
        println("outer caught")
    }
}

import kotlinx.coroutines.*

fun main() = runBlocking {
    val h = CoroutineExceptionHandler { _, e -> println("caught ${e.message}") }
    supervisorScope {
        launch(h) { throw IllegalStateException("x") }
        launch { delay(10); println("sibling ok") }
    }
    println("done")
}
